export type AssetProfileId =
  | 'character-portrait'
  | 'map-pin'
  | 'look-reference'
  | 'item-thumbnail'
  | 'user-avatar';

export type MediaByteBudget = {
  readonly targetBytes: number;
  readonly maxUploadBytes: number;
};

export type MediaOptimizeInputMeta = {
  readonly kind: MediaKind;
  readonly profileId: AssetProfileId;
  readonly mimeType: string;
  readonly byteSize: number;
  readonly width?: number;
  readonly height?: number;
  /** True when source is an animated GIF (or similar) that must not be silently flattened. */
  readonly hasAnimation?: boolean;
  /** True when source has an alpha channel that policy must preserve. */
  readonly hasAlpha?: boolean;
};

type MediaOptimizeResultBase = {
  readonly kind: MediaKind;
  readonly profileId: AssetProfileId;
  readonly input: MediaOptimizeInputMeta;
};

export type MediaOptimizeOptimizedResult = MediaOptimizeResultBase & {
  readonly status: 'optimized';
  readonly outputMimeType: string;
  readonly outputByteSize: number;
  readonly width?: number;
  readonly height?: number;
};

export type MediaOptimizeUnchangedResult = MediaOptimizeResultBase & {
  readonly status: 'unchanged';
  /** Echo of the validated original — required for unchanged. */
  readonly outputMimeType: string;
  readonly outputByteSize: number;
};

export type MediaOptimizeUnsupportedResult = MediaOptimizeResultBase & {
  readonly status: 'unsupported';
  readonly code: MediaOptimizeFailureCode;
  readonly message: string;
};

export type MediaOptimizeOverBudgetResult = MediaOptimizeResultBase & {
  readonly status: 'over-budget';
  readonly code: 'over-max-upload' | 'over-aggregate-budget';
  readonly message: string;
  readonly attemptedByteSize?: number;
};

export type MediaOptimizeAbortedResult = MediaOptimizeResultBase & {
  readonly status: 'aborted';
  readonly code: 'aborted';
  readonly message: string;
};

export type MediaOptimizeFailedResult = MediaOptimizeResultBase & {
  readonly status: 'failed';
  readonly code: MediaOptimizeFailureCode;
  readonly message: string;
};

export type ImageAssetPolicy = {
  readonly profileId: AssetProfileId;
  readonly kind: 'image';
  readonly allowedMimeTypes: readonly string[];
  readonly budget: MediaByteBudget;
  /** Soft max dimension hint for later engines (not a hard encode floor here). */
  readonly maxEdgePx: number;
  readonly minQuality: number;
  readonly preserveAlpha: boolean;
  readonly gifAnimation: GifAnimationPolicy;
  /** When false, engines must not emit WebP until coordinated migration completes. */
  readonly allowWebpOutput: boolean;
  readonly maxImagesPerRequest?: number;
  /** Hard aggregate JSON/Base64 request ceiling (Look analysis). */
  readonly maxAggregateRequestBytes?: number;
};

export type UnsupportedKindPolicy = {
  readonly profileId: AssetProfileId;
  readonly kind: Exclude<MediaKind, 'image'>;
  readonly supported: false;
  readonly message: string;
};

export type MediaPolicyEvaluation =
  | { readonly ok: true; readonly policy: ImageAssetPolicy }
  | {
      readonly ok: false;
      readonly reason:
        | 'unsupported-mime'
        | 'over-max-upload'
        | 'gif-not-allowed'
        | 'animation-not-allowed'
        | 'too-many-images'
        | 'over-aggregate-budget';
      readonly message: string;
      readonly policy: ImageAssetPolicy;
    };

export type UserProfileVm = {
  readonly id: string;
  readonly displayName: string | null;
  readonly avatarPath: string | null;
  /** Signed or resolvable URL for UI; null when no avatar_path. */
  readonly avatarUrl: string | null;
  readonly updatedAt: string | null;
};

export type AccountDisplayNameInput = {
  readonly profileDisplayName?: string | null;
  readonly authDisplayName?: string | null;
  readonly authUsername?: string | null;
  readonly email?: string | null;
};

export type AudioEngineRequest = {
  readonly input: MediaOptimizeInputMeta;
  readonly signal?: AbortSignal;
};

export type ImageWorkerEncodeRequest = {
  readonly type: 'encode';
  readonly requestId: string;
  readonly width: number;
  readonly height: number;
  /** RGBA pixel buffer (transferred). */
  readonly rgba: ArrayBuffer;
  readonly targetBytes: number;
  readonly maxUploadBytes: number;
  readonly maxOutputBytes: number;
  readonly minQuality: number;
  readonly minEdgePx?: number;
};

export type ImageWorkerResponse =
  | {
      readonly type: 'result';
      readonly requestId: string;
      readonly ok: true;
      readonly buffer: ArrayBuffer;
      readonly width: number;
      readonly height: number;
    }
  | {
      readonly type: 'result';
      readonly requestId: string;
      readonly ok: false;
      readonly reason: 'over-budget' | 'encode-failed' | 'aborted';
      readonly message: string;
      readonly attemptedByteSize?: number;
    };

export type ResourceLimitFailure = {
  readonly ok: false;
  readonly code: 'invalid-input' | 'over-max-upload';
  readonly message: string;
};

export type ImageEngineRequest = {
  readonly input: MediaOptimizeInputMeta;
  readonly signal?: AbortSignal;
  /** Raw image bytes — required for encode/decode. */
  readonly bytes?: Blob | ArrayBuffer | Uint8Array;
  readonly imageCountInRequest?: number;
  readonly aggregateRequestBytes?: number;
  /** Optional sink for optimized WebP bytes (keeps Blob out of domain results). */
  readonly onOptimizedBytes?: (bytes: Uint8Array) => void;
};

export type WebpEncodeOptions = {
  readonly lossless?: number;
  readonly exact?: number;
  readonly quality?: number;
  readonly method?: number;
  readonly alpha_quality?: number;
};

export type WebpEncodeFn = (
  data: ImageData,
  opts: WebpEncodeOptions,
) => Promise<ArrayBuffer>;

export type ScaleImageDataFn = (
  source: ImageData,
  targetW: number,
  targetH: number,
) => Promise<ImageData>;

export type WebpBudgetParams = {
  readonly imageData: ImageData;
  readonly encode: WebpEncodeFn;
  readonly scaleImageData: ScaleImageDataFn;
  /** Soft goal for the ladder (preferred encoded size). */
  readonly targetBytes: number;
  /** Hard ceiling — failure if nothing ≤ this. */
  readonly maxUploadBytes: number;
  /** Reject candidates larger than the original payload (kein Dateiwachstum). */
  readonly maxOutputBytes: number;
  readonly minQuality: number;
  readonly minEdgePx?: number;
  readonly signal?: AbortSignal;
};

export type WebpBudgetSuccess = {
  readonly ok: true;
  readonly buffer: ArrayBuffer;
  readonly width: number;
  readonly height: number;
};

export type WebpBudgetFailure = {
  readonly ok: false;
  readonly reason: 'over-budget' | 'aborted' | 'encode-failed';
  readonly message: string;
  readonly attemptedByteSize?: number;
};

export type WorkerEncodeParams = {
  readonly imageData: ImageData;
  readonly targetBytes: number;
  readonly maxUploadBytes: number;
  readonly maxOutputBytes: number;
  readonly minQuality: number;
  readonly minEdgePx?: number;
  readonly signal?: AbortSignal;
};

export type Model3dEngineRequest = {
  readonly input: MediaOptimizeInputMeta;
  readonly signal?: AbortSignal;
};

export type VideoEngineRequest = {
  readonly input: MediaOptimizeInputMeta;
  readonly signal?: AbortSignal;
};

export type OptimizeMediaRequest = {
  readonly kind: MediaKind;
  readonly profileId: AssetProfileId;
  readonly mimeType: string;
  readonly byteSize: number;
  readonly width?: number;
  readonly height?: number;
  readonly hasAnimation?: boolean;
  readonly hasAlpha?: boolean;
  readonly signal?: AbortSignal;
  /** Image payload for the WebP engine (#630); ignored by stub engines. */
  readonly bytes?: Blob | ArrayBuffer | Uint8Array;
  readonly imageCountInRequest?: number;
  readonly aggregateRequestBytes?: number;
  readonly onOptimizedBytes?: (bytes: Uint8Array) => void;
};

